CREATE TYPE "InventoryBatchStatus" AS ENUM ('AVAILABLE','RESERVED','DEPLETED','EXPIRED','QUARANTINED','DISPOSED');
CREATE TYPE "StockMovementType" AS ENUM ('RECEIPT','RESERVE','RELEASE','ISSUE','ADJUST_IN','ADJUST_OUT','COUNT_CORRECTION','DAMAGE','EXPIRY','DISPOSAL');
CREATE TYPE "InventoryReservationStatus" AS ENUM ('ACTIVE','RELEASED','FULFILLED','EXPIRED','CANCELLED');
CREATE TYPE "StockCountStatus" AS ENUM ('OPEN','CLOSED','CANCELLED');
CREATE TABLE "inventory_categories" ("id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "inventory_categories_pkey" PRIMARY KEY ("id"));
CREATE TABLE "inventory_items" ("id" UUID NOT NULL,"categoryId" UUID NOT NULL,"sku" TEXT NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"unit" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "inventory_items_pkey" PRIMARY KEY ("id"));
CREATE TABLE "inventory_locations" ("id" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "inventory_locations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "inventory_batches" ("id" UUID NOT NULL,"itemId" UUID NOT NULL,"locationId" UUID NOT NULL,"sourcePhysicalDonationLineId" UUID NOT NULL,"batchNumber" TEXT NOT NULL,"receivedQuantity" INTEGER NOT NULL,"availableQuantity" INTEGER NOT NULL,"reservedQuantity" INTEGER NOT NULL DEFAULT 0,"issuedQuantity" INTEGER NOT NULL DEFAULT 0,"damagedQuantity" INTEGER NOT NULL DEFAULT 0,"expiresAt" TIMESTAMP(3),"status" "InventoryBatchStatus" NOT NULL DEFAULT 'AVAILABLE',"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "inventory_batches_pkey" PRIMARY KEY ("id"));
CREATE TABLE "stock_movements" ("id" UUID NOT NULL,"batchId" UUID NOT NULL,"type" "StockMovementType" NOT NULL,"quantity" INTEGER NOT NULL,"availableAfter" INTEGER NOT NULL,"reservedAfter" INTEGER NOT NULL,"referenceType" TEXT NOT NULL,"referenceId" TEXT NOT NULL,"reason" TEXT,"actorUserId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "stock_movements_pkey" PRIMARY KEY ("id"));
CREATE TABLE "inventory_reservations" ("id" UUID NOT NULL,"batchId" UUID NOT NULL,"targetType" TEXT NOT NULL,"targetId" TEXT NOT NULL,"quantity" INTEGER NOT NULL,"status" "InventoryReservationStatus" NOT NULL DEFAULT 'ACTIVE',"expiresAt" TIMESTAMP(3) NOT NULL,"createdByUserId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "inventory_reservations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "stock_counts" ("id" UUID NOT NULL,"locationId" UUID NOT NULL,"status" "StockCountStatus" NOT NULL DEFAULT 'OPEN',"openedByUserId" UUID NOT NULL,"closedByUserId" UUID,"openedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"closedAt" TIMESTAMP(3),"notes" TEXT,CONSTRAINT "stock_counts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "stock_count_lines" ("id" UUID NOT NULL,"stockCountId" UUID NOT NULL,"batchId" UUID NOT NULL,"expectedQuantity" INTEGER NOT NULL,"countedQuantity" INTEGER NOT NULL,"variance" INTEGER NOT NULL,"reason" TEXT,CONSTRAINT "stock_count_lines_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "inventory_categories_code_key" ON "inventory_categories"("code");
CREATE UNIQUE INDEX "inventory_items_sku_key" ON "inventory_items"("sku");
CREATE INDEX "inventory_items_categoryId_active_idx" ON "inventory_items"("categoryId","active");
CREATE UNIQUE INDEX "inventory_items_categoryId_normalizedName_unit_key" ON "inventory_items"("categoryId","normalizedName","unit");
CREATE UNIQUE INDEX "inventory_locations_code_key" ON "inventory_locations"("code");
CREATE UNIQUE INDEX "inventory_batches_sourcePhysicalDonationLineId_key" ON "inventory_batches"("sourcePhysicalDonationLineId");
CREATE UNIQUE INDEX "inventory_batches_batchNumber_key" ON "inventory_batches"("batchNumber");
CREATE INDEX "inventory_batches_itemId_status_expiresAt_idx" ON "inventory_batches"("itemId","status","expiresAt");
CREATE INDEX "inventory_batches_locationId_status_idx" ON "inventory_batches"("locationId","status");
CREATE INDEX "stock_movements_batchId_createdAt_idx" ON "stock_movements"("batchId","createdAt");
CREATE INDEX "stock_movements_referenceType_referenceId_idx" ON "stock_movements"("referenceType","referenceId");
CREATE UNIQUE INDEX "stock_movements_batchId_type_referenceType_referenceId_key" ON "stock_movements"("batchId","type","referenceType","referenceId");
CREATE INDEX "inventory_reservations_status_expiresAt_idx" ON "inventory_reservations"("status","expiresAt");
CREATE UNIQUE INDEX "inventory_reservations_batchId_targetType_targetId_key" ON "inventory_reservations"("batchId","targetType","targetId");
CREATE INDEX "stock_counts_locationId_status_idx" ON "stock_counts"("locationId","status");
CREATE UNIQUE INDEX "stock_count_lines_stockCountId_batchId_key" ON "stock_count_lines"("stockCountId","batchId");
ALTER TABLE "inventory_items" ADD CONSTRAINT "inventory_items_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "inventory_categories"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "inventory_batches" ADD CONSTRAINT "inventory_batches_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "inventory_items"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "inventory_batches" ADD CONSTRAINT "inventory_batches_locationId_fkey" FOREIGN KEY ("locationId") REFERENCES "inventory_locations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "inventory_batches" ADD CONSTRAINT "inventory_batches_sourcePhysicalDonationLineId_fkey" FOREIGN KEY ("sourcePhysicalDonationLineId") REFERENCES "physical_donation_lines"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "stock_movements" ADD CONSTRAINT "stock_movements_batchId_fkey" FOREIGN KEY ("batchId") REFERENCES "inventory_batches"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "inventory_reservations" ADD CONSTRAINT "inventory_reservations_batchId_fkey" FOREIGN KEY ("batchId") REFERENCES "inventory_batches"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "stock_count_lines" ADD CONSTRAINT "stock_count_lines_stockCountId_fkey" FOREIGN KEY ("stockCountId") REFERENCES "stock_counts"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "stock_count_lines" ADD CONSTRAINT "stock_count_lines_batchId_fkey" FOREIGN KEY ("batchId") REFERENCES "inventory_batches"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
